-- BEGIN 20261115160000 20261115_rc1_25_skus_and_stock_audits; source(s): supabase/migrations/propostas/20261115_rc1_25_skus_and_stock_audits.sql sha256=8AAF49416C581EAEAAFC31BDFE7C769CA289C2444577A917FBCC769AECC018F5
-- ==============================================================================
-- MK9 COMMAND CENTER - MIGRAÇÃO DE CATÁLOGO DE SKUS E CONFERÊNCIA DE ESTOQUE
-- Arquivo: supabase/migrations/propostas/20261115_rc1_25_skus_and_stock_audits.sql
